import { chargeCard } from "../lib/payments.js";
import { db } from "../lib/db.js";

export async function checkout(req, res) {
  const { cartId, paymentMethodId } = req.body;
  const cart = await db.carts.findById(cartId);
  if (!cart) return res.status(404).json({ error: "cart not found" });

  const total = cart.items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const charge = await chargeCard({ amount: total, paymentMethodId });

  await db.orders.insert({ cartId, chargeId: charge.id, total, status: "paid" });
  await db.carts.delete(cartId);
  return res.json({ ok: true, chargeId: charge.id });
}

import { gateway } from "./gateway.js";

const MAX_ATTEMPTS = 3;

export async function chargeCard({ amount, paymentMethodId }) {
  let lastError;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      return await gateway.charges.create({
        amount: Math.round(amount * 100),
        currency: "usd",
        payment_method: paymentMethodId,
      });
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError;
}
